const $ = (s) => document.querySelector(s);
const state = { all: [], filtered: [], abilities: {}, moves: {}, selected: null, tab: 'overview', compare: [] };
const statNames = ['HP', 'Tấn công', 'Phòng thủ', 'T.ĐB', 'P.ĐB', 'Tốc độ'];
const colors = { BUG:'#8da83e',WATER:'#4b94cf',FIRE:'#e47b47',GRASS:'#6eaf58',ELECTRIC:'#cba83c',ICE:'#68b8c6',FIGHTING:'#b66a50',POISON:'#a376bc',GROUND:'#b6955c',FLYING:'#819cd0',PSYCHIC:'#dc709e',ROCK:'#9a8b67',GHOST:'#7770a9',DRAGON:'#657ab9',DARK:'#665f75',STEEL:'#78979d',FAIRY:'#d588b7',NORMAL:'#838f97'};
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId = id => state.all.find(p => p.id === id);
const label = (id, table) => table[id]?.name || id;
const sprite = (p, size='large') => p.sprite ? `<img src="./sprites/${encodeURIComponent(p.sprite)}" alt="Sprite ${esc(p.name)}" loading="lazy">` : `<span class="no-art">${esc(size === 'small' ? p.name : 'Chưa có sprite')}</span>`;
const types = p => `<span class="types">${p.types.map(t => `<span class="type" style="--type-bg:${colors[t] || '#637f88'}">${esc(t)}</span>`).join('')}</span>`;
const title = p => p.formName ? `${p.name} · ${p.formName}` : p.name;
const total = p => p.stats.reduce((a,b) => a+b,0);

function applyFilters() {
  const q = $('#search').value.trim().toLocaleLowerCase();
  const type = $('#typeFilter').value, group = $('#groupFilter').value;
  state.filtered = state.all.filter(p => (group==='all' || (group==='forms' ? p.isForm : !p.isForm)) && (!type || p.types.includes(type)) && (!q || [p.id,p.name,p.formName,p.category,...p.abilities,...p.hidden,...p.innates].some(v => String(v).toLocaleLowerCase().includes(q))));
  const sort = $('#sort').value;
  state.filtered.sort((a,b) => sort==='bst' ? total(b)-total(a) || a.name.localeCompare(b.name) : sort==='generation' ? (+a.generation||99)-(+b.generation||99) || a.name.localeCompare(b.name) : a.name.localeCompare(b.name) || a.id.localeCompare(b.id));
  $('#resultCount').textContent = `${state.filtered.length.toLocaleString('vi-VN')} kết quả`;
  renderList();
}
function renderList() {
  const selected = state.selected?.id;
  $('#pokemonList').innerHTML = state.filtered.length ? state.filtered.map(p => `<button class="mon-card ${p.id===selected?'active':''}" data-id="${esc(p.id)}" aria-label="Xem ${esc(title(p))}" ${p.id===selected?'aria-current="true"':''}><span class="mini-art">${sprite(p,'small')}</span><span><span class="mon-name">${esc(p.name)}</span><span class="mon-id">${esc(p.id)}${p.formName?' · '+esc(p.formName):''}</span>${types(p)}</span><span class="card-bst">${total(p)||'—'}</span></button>`).join('') : '<p class="empty" style="padding:8px 14px">Không tìm thấy Pokémon phù hợp.</p>';
}
function abilityItems(ids) {return ids.length ? ids.map(id => `<div class="data-item"><strong class="ability-pill">${esc(label(id,state.abilities))}</strong><p>${esc(state.abilities[id]?.description || id)}</p></div>`).join('') : '<p class="empty">Chưa có dữ liệu.</p>'}
function overview(p) {
  return `<div class="panel-grid"><div class="panel-box"><h3>Chỉ số cơ bản</h3>${statNames.map((name,i)=>`<div class="stat-row"><span>${name}</span><strong>${p.stats[i]??'—'}</strong><span class="stat-track"><span class="stat-fill" style="display:block;width:${Math.min(100,(p.stats[i]||0)/255*100)}%"></span></span></div>`).join('')}<div class="stat-total"><span>Tổng chỉ số</span><b>${total(p)}</b></div></div><div class="data-list"><div class="panel-box"><h3>Đặc tính</h3>${abilityItems(p.abilities)}${p.hidden.length?`<div class="data-item"><small>Đặc tính ẩn</small>${abilityItems(p.hidden)}</div>`:''}</div><div class="panel-box"><h3>Innates</h3>${p.innates.length?p.innates.map(id=>`<div class="data-item"><strong class="ability-pill innate">${esc(label(id,state.abilities))}</strong><p>${esc(state.abilities[id]?.description || id)}</p></div>`).join(''):'<p class="empty">Loài này không có mục trong innate_sets.txt.</p>'}</div></div></div>`;
}
function moveTable(list, tutor=false) {return list.length ? `<div class="table-scroll"><table class="move-table"><thead><tr><th>${tutor?'STT':'Cấp'}</th><th>Chiêu thức</th><th>Hệ</th><th>Loại</th><th>Sức mạnh</th></tr></thead><tbody>${list.map((item,i)=>{const id=tutor?item:item.id,m=state.moves[id]||{};return `<tr><td>${tutor?i+1:esc(item.level)}</td><td title="${esc(m.description||'')}">${esc(label(id,state.moves))}</td><td>${m.type?`<span class="type" style="--type-bg:${colors[m.type]||'#637f88'}">${esc(m.type)}</span>`:'—'}</td><td>${esc(({Physical:'Vật lý',Special:'Đặc biệt',Status:'Trạng thái'})[m.category]||m.category||'—')}</td><td>${esc(m.power&&m.power!=='0'?m.power:'—')}</td></tr>`}).join('')}</tbody></table></div>` : `<p class="empty">${tutor?'Chưa có chiêu TM / Tutor.':'Chưa có chiêu học theo cấp.'}</p>`}
function moveChips(ids){return ids.length?`<div class="move-chips">${ids.map(id=>`<span class="move-chip" title="${esc(state.moves[id]?.description||'')}">${esc(label(id,state.moves))}</span>`).join('')}</div>`:'<p class="empty">Chưa có dữ liệu.</p>'}
function moves(p) {return `<div class="moves-layout"><div class="panel-box"><h3>Chiêu học theo cấp <small>(${p.moves.length})</small></h3>${moveTable(p.moves)}</div><div class="panel-box"><h3>Chiêu học từ TM / Tutor <small>(${p.tutor.length})</small></h3>${moveTable(p.tutor,true)}</div><div class="panel-box"><h3>Egg Moves <small>(${p.egg.length})</small></h3>${moveChips(p.egg)}</div></div>`}
function evolution(p){let prev=state.all.filter(x=>!x.isForm && x.evolutions.some(e=>e.to===p.species));let out=p.evolutions;return `<div class="panel-box"><h3>Tiến hóa</h3><div class="evolution-chain">${prev.map(x=>x.evolutions.filter(e=>e.to===p.species).map(e=>`<div class="evo-row"><button class="evo-link" data-evo="${esc(x.id)}">${esc(x.name)}</button><span class="evo-method">${esc(e.method)} ${esc(e.value)}</span><button class="evo-link" data-evo="${esc(p.id)}">${esc(p.name)}</button></div>`).join('')).join('')}${out.map(e=>`<div class="evo-row"><button class="evo-link" data-evo="${esc(p.id)}">${esc(p.name)}</button><span class="evo-method">${esc(e.method)} ${esc(e.value)}</span>${byId(e.to)?`<button class="evo-link" data-evo="${esc(e.to)}">${esc(byId(e.to).name)}</button>`:`<span>${esc(e.to)}</span>`}</div>`).join('')}${!prev.length&&!out.length?'<p class="empty">PBS không khai báo tiến hóa cho dạng này.</p>':''}</div></div>`}
function show(id) {
  const p=byId(id);if(!p)return;state.selected=p;
  const checked=state.compare.includes(p.id);
  $('#detail').innerHTML=`<div class="hero"><div class="hero-image">${sprite(p)}</div><div class="hero-copy"><span class="hero-kicker">${esc(p.id)} ${p.generation?'· GEN '+esc(p.generation):''}</span><h2>${esc(p.name)}</h2>${p.formName?`<div class="form-label">${esc(p.formName)}</div>`:''}${types(p)}<div class="form-label">${esc(p.category?`${p.category} Pokémon`:'Pokémon')}</div><p class="dex-entry">${esc(p.description||'Chưa có Dex Entry trong PBS.')}</p><div class="hero-bottom"><span class="meta-chip">Chiều cao <b>${esc(p.height||'—')} m</b></span><span class="meta-chip">Cân nặng <b>${esc(p.weight||'—')} kg</b></span><button class="compare-toggle ${checked?'selected':''}" id="toggleCompare">${checked?'✓ Đã chọn so sánh':'+ So sánh'}</button></div></div></div><nav class="tabs" aria-label="Thông tin Pokémon"><button data-tab="overview" class="${state.tab==='overview'?'active':''}">Tổng quan</button><button data-tab="moves" class="${state.tab==='moves'?'active':''}">Chiêu thức</button><button data-tab="evolution" class="${state.tab==='evolution'?'active':''}">Tiến hóa</button></nav><div class="panel">${state.tab==='moves'?moves(p):state.tab==='evolution'?evolution(p):overview(p)}</div>`;
  renderList();history.replaceState(null,'',`#${encodeURIComponent(p.id)}`);
}
function syncCompare(){const arr=state.compare.map(byId).filter(Boolean);$('#compareBar').hidden=!arr.length;$('#compareNames').textContent=arr.map(title).join('  ·  ');$('#openCompare').disabled=arr.length!==2}
function compareView(){const arr=state.compare.map(byId);if(arr.length!==2)return;$('#compareContent').innerHTML=`<div class="comparison">${arr.map(p=>`<div class="panel-box"><div class="mini-art">${sprite(p,'small')}</div><h3>${esc(title(p))}</h3>${statNames.map((n,i)=>`<div class="stat-row"><span>${n}</span><strong>${p.stats[i]??'—'}</strong><span class="stat-track"><span class="stat-fill" style="display:block;width:${Math.min(100,(p.stats[i]||0)/255*100)}%"></span></span></div>`).join('')}<div class="stat-total"><span>Tổng</span><b>${total(p)}</b></div></div>`).join('')}</div>`;$('#compareDialog').showModal()}
document.addEventListener('click',e=>{const card=e.target.closest('[data-id]');if(card){show(card.dataset.id);if(innerWidth<=700)$('#detail').scrollIntoView({behavior:'smooth'});return}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;show(state.selected.id);return}const evo=e.target.closest('[data-evo]');if(evo){state.tab='overview';show(evo.dataset.evo);$('#detail').scrollIntoView({behavior:'smooth'});return}if(e.target.closest('#toggleCompare')){let id=state.selected.id;state.compare=state.compare.includes(id)?state.compare.filter(x=>x!==id):[...state.compare.slice(-1),id];syncCompare();show(id)}});
['search','typeFilter','groupFilter','sort'].forEach(k=>$('#'+k).addEventListener(k==='search'?'input':'change',applyFilters));
document.addEventListener('keydown',e=>{if(e.key==='/' && !['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});
$('#openCompare').onclick=compareView;$('#closeCompare').onclick=()=>$('#compareDialog').close();$('#clearCompare').onclick=()=>{state.compare=[];syncCompare();show(state.selected.id)};
$('#refreshData').onclick=()=>location.reload();
fetch('./data.json').then(r=>{if(!r.ok)throw new Error('Không tải được data.json');return r.json()}).then(data=>{state.all=data.pokemon;state.abilities=data.abilities;state.moves=data.moves;$('#totalCount').textContent=`${state.all.filter(p=>!p.isForm).length.toLocaleString('vi-VN')} loài · ${state.all.filter(p=>p.isForm).length.toLocaleString('vi-VN')} dạng`;const ts=[...new Set(state.all.flatMap(p=>p.types))].sort();$('#typeFilter').innerHTML+=[...ts].map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');const hash=decodeURIComponent(location.hash.slice(1));const selected=byId(hash)||state.all.find(p=>p.id==='ROWBUG')||state.all[0];applyFilters();show(selected.id)}).catch(err=>{$('#detail').innerHTML=`<div class="panel-box"><h3>Không đọc được dữ liệu</h3><p class="empty">${esc(err.message)}. Hãy mở trang bằng máy chủ web thay vì nhấp trực tiếp file HTML.</p></div>`;$('#totalCount').textContent='Lỗi tải dữ liệu'});
